const upsertAnimeMapping = `-- name: UpsertAnimeMapping :exec
INSERT INTO anime_mappings (anilist, mal, anidb, tvdb, tmdb, tmdb_season)
VALUES ($1, $2, $3, $4, $5, $6)
ON CONFLICT (anilist) DO UPDATE SET
    mal = EXCLUDED.mal, anidb = EXCLUDED.anidb, tvdb = EXCLUDED.tvdb,
    tmdb = EXCLUDED.tmdb, tmdb_season = EXCLUDED.tmdb_season
`

type UpsertAnimeMappingParams struct {
	Anilist    string
	Mal        *string
	Anidb      *string
	Tvdb       *string
	Tmdb       *string
	TmdbSeason *int32
}

func (q *Queries) UpsertAnimeMapping(ctx context.Context, arg UpsertAnimeMappingParams) error {
	_, err := q.db.Exec(ctx, upsertAnimeMapping,
		arg.Anilist,
		arg.Mal,
		arg.Anidb,
		arg.Tvdb,
		arg.Tmdb,
		arg.TmdbSeason,
	)
	return err
}
